import { describe, expect, it } from "bun:test";
import { Phases } from "../src/constants";
import { fetchSingleNode } from "../src/request";

const ALIAS = "parent_alias_replay";
const PARENT_V1 = "parent_v1_alias_replay";
const PARENT_BAD = "parent_bad_alias_replay";
const CHILDREN = "children_alias_replay";

async function joinedChildCount(): Promise<number> {
  const filterBy = `$${ALIAS}(code:=\`ok\`)`;
  const res = await fetchSingleNode(
    `/collections/${CHILDREN}/documents/search?q=*&query_by=parent_code&filter_by=${encodeURIComponent(filterBy)}`,
  );
  expect(res.ok).toBe(true);
  return (await res.json() as { found: number }).found;
}

describe(Phases.SINGLE_FRESH, () => {
  it("rejects an incompatible async-reference alias swap", async () => {
    let res = await fetchSingleNode("/collections", {
      method: "POST",
      body: JSON.stringify({
        name: PARENT_V1,
        fields: [{ name: "code", type: "string", facet: true }],
      }),
    });
    expect(res.ok).toBe(true);

    res = await fetchSingleNode(`/aliases/${ALIAS}`, {
      method: "PUT",
      body: JSON.stringify({ collection_name: PARENT_V1 }),
    });
    expect(res.ok).toBe(true);

    res = await fetchSingleNode("/collections", {
      method: "POST",
      body: JSON.stringify({
        name: CHILDREN,
        fields: [{
          name: "parent_code",
          type: "string",
          reference: `${ALIAS}.code`,
          async_reference: true,
        }],
      }),
    });
    expect(res.ok).toBe(true);

    res = await fetchSingleNode(`/collections/${PARENT_V1}/documents`, {
      method: "POST",
      body: JSON.stringify({ id: "p-1", code: "ok" }),
    });
    expect(res.ok).toBe(true);

    res = await fetchSingleNode(`/collections/${CHILDREN}/documents`, {
      method: "POST",
      body: JSON.stringify({ id: "c-1", parent_code: "ok" }),
    });
    expect(res.ok).toBe(true);
    expect(await joinedChildCount()).toBe(1);

    res = await fetchSingleNode("/collections", {
      method: "POST",
      body: JSON.stringify({
        name: PARENT_BAD,
        fields: [{ name: "other", type: "string" }],
      }),
    });
    expect(res.ok).toBe(true);

    res = await fetchSingleNode(`/aliases/${ALIAS}`, {
      method: "PUT",
      body: JSON.stringify({ collection_name: PARENT_BAD }),
    });
    expect(res.status).toBe(500);
    expect((await res.json() as { message: string }).message).toContain("Referenced field `code` not found");
  });
});

describe(Phases.SINGLE_RESTARTED, () => {
  it("keeps the prior alias target and async join after restart", async () => {
    const res = await fetchSingleNode(`/aliases/${ALIAS}`);
    expect(res.ok).toBe(true);
    expect((await res.json() as { collection_name: string }).collection_name).toBe(PARENT_V1);
    expect(await joinedChildCount()).toBe(1);
  });
});

import { describe, it, expect } from "bun:test";
import { Phases } from "../src/constants";
import { fetchSingleNode } from "../src/request";

// a field declared `store: false` is stripped before the document is written to
// disk. when it is also `optional: false`, the reloaded document used to fail
// validation and the whole collection loaded 0 documents, silently
// the documents must survive a restart and a snapshot restore. SINGLE_SNAPSHOT
// is the important phase. The snapshot truncates the raft log, so the 
// restart is a true cold-load from the on-disk store.
const COLLECTION = "store_false_reload";

async function foundCount(): Promise<number> {
  const res = await fetchSingleNode(
    `/collections/${COLLECTION}/documents/search?q=*&per_page=250`,
    { method: "GET" },
  );
  expect(res.ok).toBe(true);
  const body: any = await res.json();
  return body.found as number;
}

describe(Phases.SINGLE_FRESH, () => {
  it("seed store:false + optional:false fields", async () => {
    let res = await fetchSingleNode("/collections", {
      method: "POST",
      body: JSON.stringify({
        name: COLLECTION,
        fields: [
          { name: "title", type: "string" },
          { name: "embedding", type: "float[]", num_dim: 4, optional: false, store: false },
          { name: "secret", type: "string", optional: false, store: false },
        ],
      }),
    });
    expect(res.ok).toBe(true);

    const jsonl = [
      JSON.stringify({ id: "1", title: "alpha", embedding: [0.1, 0.2, 0.3, 0.4], secret: "s1" }),
      JSON.stringify({ id: "2", title: "bravo", embedding: [0.2, 0.3, 0.4, 0.5], secret: "s2" }),
      JSON.stringify({ id: "3", title: "charlie", embedding: [0.3, 0.4, 0.5, 0.6], secret: "s3" }),
    ].join("\n");
    res = await fetchSingleNode(
      `/collections/${COLLECTION}/documents/import?action=create`,
      { method: "POST", body: jsonl },
    );
    expect(res.ok).toBe(true);
    const importBody = await res.text();
    expect(importBody.split("\n").every((l) => l.includes('"success":true'))).toBe(true);

    expect(await foundCount()).toBe(3);
  });

  it("returns the stored field but not the unstored ones", async () => {
    const res = await fetchSingleNode(
      `/collections/${COLLECTION}/documents/search?q=*&per_page=250`,
      { method: "GET" },
    );
    expect(res.ok).toBe(true);
    const body: any = await res.json();
    const doc = body.hits[0].document;
    expect(doc.title).toBeDefined();
    expect(doc.embedding).toBeUndefined();
    expect(doc.secret).toBeUndefined();
  });
});

describe(Phases.SINGLE_RESTARTED, () => {
  it("documents survive a restart", async () => {
    expect(await foundCount()).toBe(3);
  });
});

describe(Phases.SINGLE_SNAPSHOT, () => {
  it("documents survive a snapshot restore (cold-load from store)", async () => {
    expect(await foundCount()).toBe(3);
  });
});

const DELAY_INTERVALS = [10, 100, 1000, 2000, 3000, 4000];

export async function fetchSingleNode(url: string, options?: RequestInit, port: number = 8108) {
  const res = await fetch(`http://localhost:${port}${url}`, {
    ...options,
    headers: {
      ...options?.headers,
      "X-TYPESENSE-API-KEY": "xyz",
    },
    signal: AbortSignal.timeout(30000),
  });
  return res;
}

export async function fetchMultiNodeRequest(node: number, url: string, options?: RequestInit): Promise<Response> {
  const res = await fetch(`http://localhost:${node + 4}108${url}`, {
    ...options,
    headers: {
      ...options?.headers,
      "X-TYPESENSE-API-KEY": "xyz",
    },
    signal: AbortSignal.timeout(30000),
  });
  return res;
}

export async function fetchMultiNode(node: number, url: string, options?: RequestInit): Promise<Response> {
  for(let i = 0; i < DELAY_INTERVALS.length; i++) {
    const isSync = await checkCommitedIndex();
    if(isSync) {
      break;
    }
    await new Promise(resolve => setTimeout(resolve, DELAY_INTERVALS[i]));
  }
  const res = await fetchMultiNodeRequest(node, url, options);
  return res;
}

export async function checkCommitedIndex() {
  const res = await Promise.all([
    fetchMultiNodeRequest(1, "/status"),
    fetchMultiNodeRequest(2, "/status"),
    fetchMultiNodeRequest(3, "/status"),
  ]);

  const data = await Promise.all(res.map(r => r.json()));
  const last_indexes = data.map((d: any) => d.last_index);
  const committed_indexes = data.map((d: any) => d.committed_index);
  const applied_indexes = data.map((d: any) =>
    d.applying_index === 0 ? d.known_applied_index : d.applying_index,
  );

  if(committed_indexes[0] !== committed_indexes[1] || committed_indexes[0] !== committed_indexes[2]) {
    return false;
  }

  return committed_indexes.every((committed_index: number, index: number) => {
    return last_indexes[index] === committed_index && committed_index === applied_indexes[index];
  });
}

export async function waitForSingleAnalyticsFlush() {
  await fetchSingleNode("/analytics/flush", { method: "POST" });
  for(let i = 0; i < DELAY_INTERVALS.length; i++) {
    const res = await fetchSingleNode("/analytics/status");
    const data: any = await res.json();
    let isSync = true;
    for(const key in data) {
      if(data[key] !== 0) {
        isSync = false;
        break;
      }
    }
    if(isSync) {
      break;
    }
    await new Promise(resolve => setTimeout(resolve, DELAY_INTERVALS[i]));
  }
}

export async function waitForMultiAnalyticsFlush() {
  await Promise.all([
    fetchMultiNodeRequest(1, "/analytics/flush", { method: "POST" }),
    fetchMultiNodeRequest(2, "/analytics/flush", { method: "POST" }),
    fetchMultiNodeRequest(3, "/analytics/flush", { method: "POST" }),
  ]);

  for(let i = 0; i < DELAY_INTERVALS.length; i++) {
    const res = await Promise.all([
      fetchMultiNodeRequest(1, "/analytics/status"),
      fetchMultiNodeRequest(2, "/analytics/status"),
      fetchMultiNodeRequest(3, "/analytics/status"),
    ]);
    const data: any[] = await Promise.all(res.map(r => r.json()));
    let isSync = true;
    for(const d of data) {
      for(const key in d) {
        if(d[key] !== 0) {
          isSync = false;
          break;
        }
      }
    }
    if(isSync) {
      break;
    }
    await new Promise(resolve => setTimeout(resolve, DELAY_INTERVALS[i]));
  }
}

import { beforeAll, describe, expect, it } from "bun:test";
import { z } from "zod";
import { Phases } from "../src/constants";
import { fetchSingleNode } from "../src/request";

const UnionResponse = z.object({
  found: z.number(),
  search_cutoff: z.boolean(),
  hits: z.array(
    z.object({
      document: z.object({ id: z.string() }),
      curated: z.boolean().optional(),
    }),
  ),
});

const ErrorResponse = z.object({ message: z.string() });

const COLLECTIONS = ["union_cutoff_0", "union_cutoff_1"];
const DOCS_PER_COLLECTION = 50;

// A search's cutoff is measured from the time the server received the request,
// so a budget of 0 ms is spent before the search starts. Each sub-search of a
// union resets the cutoff flag, so the union has to carry an earlier
// sub-search's cutoff past the ones that run after it.
function unionSearch(
  firstSearchParams: Record<string, unknown> = {},
  secondSearchParams: Record<string, unknown> = {},
) {
  return JSON.stringify({
    union: true,
    searches: [
      {
        collection: COLLECTIONS[0],
        q: "widget",
        query_by: "title",
        filter_by: "category:=kitchen",
        ...firstSearchParams,
      },
      {
        collection: COLLECTIONS[1],
        q: "widget",
        query_by: "title",
        filter_by: "category:=kitchen",
        ...secondSearchParams,
      },
    ],
  });
}

describe(Phases.SINGLE_FRESH, () => {
  beforeAll(async () => {
    for (const name of COLLECTIONS) {
      const created = await fetchSingleNode("/collections", {
        method: "POST",
        body: JSON.stringify({
          name,
          fields: [
            { name: "title", type: "string" },
            { name: "category", type: "string" },
          ],
        }),
      });
      expect(created.status).toBe(201);

      const jsonl = Array.from({ length: DOCS_PER_COLLECTION }, (_, i) =>
        JSON.stringify({ id: String(i), title: `widget ${i}`, category: "kitchen" }),
      ).join("\n");
      const imported = await fetchSingleNode(
        `/collections/${name}/documents/import?action=create`,
        { method: "POST", body: jsonl },
      );
      expect(imported.ok).toBe(true);
      const lines = (await imported.text()).trim().split("\n");
      expect(lines.length).toBe(DOCS_PER_COLLECTION);
      expect(lines.every((line) => line.includes('"success":true'))).toBe(true);
    }
  });

  it("serves the union in full when no budget is spent", async () => {
    const res = await fetchSingleNode("/multi_search", {
      method: "POST",
      body: unionSearch(),
    });
    expect(res.status).toBe(200);
    const data = UnionResponse.parse(await res.json());
    expect(data.search_cutoff).toBe(false);
    expect(data.found).toBe(2 * DOCS_PER_COLLECTION);
  });

  it("reports search_cutoff when an earlier sub-search was cut off", async () => {
    // Only the first sub-search has its budget spent; a pinned hit is all it
    // returns. The second runs with the default budget and returns real hits,
    // so the union succeeds but still has to report the cutoff.
    const res = await fetchSingleNode("/multi_search", {
      method: "POST",
      body: unionSearch({ search_cutoff_ms: 0, pinned_hits: "0:1" }),
    });
    expect(res.status).toBe(200);
    const data = UnionResponse.parse(await res.json());
    expect(data.search_cutoff).toBe(true);
    expect(data.found).toBe(1 + DOCS_PER_COLLECTION);
    expect(data.hits[0]?.document.id).toBe("0");
    expect(data.hits[0]?.curated).toBe(true);
  });

  it("answers 408 when a cut off union has nothing to return", async () => {
    const res = await fetchSingleNode("/multi_search", {
      method: "POST",
      body: unionSearch({ search_cutoff_ms: 0 }, { filter_by: "category:=office" }),
    });
    expect(res.status).toBe(408);
    expect(res.statusText).toBe("Request Timeout");
    const data = ErrorResponse.parse(await res.json());
    expect(data.message).toBe("Request Timeout");
  });
});

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createServer, type Server } from "node:https";
import type { AddressInfo } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Phases } from "../src/constants";
import { fetchSingleNode } from "../src/request";

let tempDir: string;
let mockServer: Server;
let mockPort: number;

function createSelfSignedCert() {
  tempDir = mkdtempSync(join(tmpdir(), "typesense-api-ssl-"));
  const configPath = join(tempDir, "openssl.cnf");
  const keyPath = join(tempDir, "key.pem");
  const certPath = join(tempDir, "cert.pem");

  writeFileSync(configPath, [
    "[req]",
    "default_bits = 2048",
    "prompt = no",
    "default_md = sha256",
    "distinguished_name = dn",
    "x509_extensions = v3_req",
    "",
    "[dn]",
    "CN = 127.0.0.1",
    "",
    "[v3_req]",
    "subjectAltName = @alt_names",
    "",
    "[alt_names]",
    "IP.1 = 127.0.0.1",
    "DNS.1 = localhost",
    "",
  ].join("\n"));

  execFileSync("openssl", [
    "req",
    "-x509",
    "-newkey", "rsa:2048",
    "-keyout", keyPath,
    "-out", certPath,
    "-days", "2",
    "-nodes",
    "-config", configPath,
  ], { stdio: "ignore" });

  return {
    key: readFileSync(keyPath),
    cert: readFileSync(certPath),
  };
}

function proxyToMock(sslVerify: boolean) {
  return fetchSingleNode("/proxy", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      url: `https://127.0.0.1:${mockPort}/ssl-check`,
      method: "GET",
      headers: {},
      ssl_verify: sslVerify,
    }),
  });
}

function proxySseToMock(sslVerify: boolean) {
  return fetchSingleNode("/proxy_sse", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      url: `https://127.0.0.1:${mockPort}/ssl-check`,
      method: "POST",
      body: "{}",
      headers: { "content-type": "application/json" },
      ssl_verify: sslVerify,
    }),
  });
}

describe(Phases.SINGLE_FRESH, () => {
  beforeAll(async () => {
    const credentials = createSelfSignedCert();
    mockServer = createServer(credentials, (_req, res) => {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify({ ok: true }));
    });

    await new Promise<void>((resolve) => mockServer.listen(0, "127.0.0.1", resolve));
    mockPort = (mockServer.address() as AddressInfo).port;
  });

  afterAll(async () => {
    if (mockServer) {
      await new Promise<void>((resolve, reject) => {
        mockServer.close((error) => error ? reject(error) : resolve());
      });
    }

    if (tempDir) {
      rmSync(tempDir, { recursive: true, force: true });
    }
  });

  it("should reject self-signed upstream certificates when ssl_verify is enabled", async () => {
    const relaxedRes = await proxyToMock(false);
    expect(relaxedRes.status).toBe(200);
    expect(await relaxedRes.json()).toEqual({ ok: true });

    const verifiedRes = await proxyToMock(true);
    expect(verifiedRes.status).toBe(500);
  });

  it("should return a deterministic SSE proxy error when SSL verification fails", async () => {
    const verifiedRes = await proxySseToMock(true);
    expect(verifiedRes.status).toBe(500);

    const body = await verifiedRes.json();
    expect(body.message).toBe("Server error on remote server. Please try again later.");
  });
});

